To solve this multi-commodity transportation problem using Gurobipy, we translate the mathematical formulation into a Python program. The goal is to minimize the total shipping cost while satisfying supply, demand, and transportation limits.

```python
import gurobipy as gp
from gurobipy import GRB

# Read parameters from input
supply = [[20, 30], [40, 10]]
demand = [[30, 30], [30, 10]]
limit = [[35, 25], [25, 30]]
cost = [[[2, 3], [4, 1]], [[3, 2], [2, 4]]]

# Create the model
env = gp.Env()
model = gp.Model(env=env)

# Initialize variables
X = {}
for i in range(2):
    for j in range(2):
        for p in range(2):
            X[i,j,p] = model.addVar(name=f'X_{i+1}_{j+1}_{p+1}', lb=0)

# Set objective function
model.setObjective(
    sum(cost[i][j][p] * X[i,j,p] for i in range(2) for j in range(2) for p in range(2)),
    GRB.MINIMIZE
)

# Add supply constraints
for i in range(2):
    for p in range(2):
        model.addConstr(
            sum(X[i,j,p] for j in range(2)) == supply[i][p],
            f'Supply_{i+1}_{p+1}'
        )

# Add demand constraints
for j in range(2):
    for p in range(2):
        model.addConstr(
            sum(X[i,j,p] for i in range(2)) == demand[j][p],
            f'Demand_{j+1}_{p+1}'
        )

# Add transportation limits
for i in range(2):
    for j in range(2):
        model.addConstr(
            sum(X[i,j,p] for p in range(2)) <= limit[i][j],
            f'Limit_{i+1}_{j+1}'
        )

# Optimize the model
model.optimize()

# Check if optimal solution is found and print total cost
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
```

