def main(env):
    # Create model
    model = gp.Model(env=env)

    # Parameters
    RollWidth = 10
    I = [1, 2, 3]  # widths: 2, 3, 5
    Orders = {1:4, 2:2, 3:2}
    NumPatterns = 2
    NumRollsWidth = {
        1: {1:1, 2:2},
        2: {1:0, 2:0},
        3: {1:0, 2:1}
    }

    # Decision variables
    x = {}
    for j in range(1, NumPatterns + 1):
        x[j] = model.addVar(name=f'x_{j}')

    # Objective function
    model.setObjective(gp.quicksum(x[j] for j in x), GRB.MINIMIZE)

    # Constraints
    for i in I:
        lhs = gp.LinExpr()
        for j in range(1, NumPatterns + 1):
            coeff = NumRollsWidth[i][j]
            if coeff > 0:
                lhs += coeff * x[j]
        model.addConstr(lhs >= Orders[i], name=f'width_{i}_constraint')

